class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        counts = defaultdict(int)
        best = maxf = l = 0
        for r, ch in enumerate(s):
            counts[ch] += 1
            maxf = max(maxf, counts[ch])
            while (r - l + 1) - maxf > k:
                counts[s[l]] -= 1
                l += 1
            best = max(best, r - l + 1)
        return best

